import type { PostalInfo } from './types'

/**
 * Offline catalog of Mexican postal codes (state, municipality, neighbourhoods), generated by `scripts/build-mx.mjs` from
 * GeoNames (CC BY 4.0; the attribution travels inside the JSON) with the same state names as OPS' `region_mx` pack.
 * Meant as the fallback behind the official OPS catalog. Never invents a result: an unknown code answers `null`.
 */
type Catalog = { states: string[]; cities: string[]; zips: Record<string, [number, number[], string[]]> }

let catalog: Promise<Catalog> | null = null
// Lazy: the JSON (~3 MB) is its own chunk and is only read the first time a lookup runs.
const load = () => (catalog ??= import('./data/mx.json').then((m) => m.default as unknown as Catalog))

/** State, municipality and neighbourhoods of a 5-digit Mexican postal code; `null` if invalid or unknown. */
export async function lookupMxPostalCode(zip: string): Promise<PostalInfo | null> {
  const five = /^\d{5}$/.exec(zip.trim())?.[0]
  if (!five) return null
  const { states, cities, zips } = await load()
  const hit = Object.hasOwn(zips, five) ? zips[five] : undefined
  const province = hit ? states[hit[0]] : undefined
  const first = hit?.[1][0]
  const city = first === undefined ? undefined : cities[first]
  if (!hit || !province || !city) return null
  const info: PostalInfo = { province, city, neighborhoods: hit[2] }
  // More than one municipality: like OPS, `cities` leaves the City field editable with those options.
  if (hit[1].length > 1) info.cities = hit[1].flatMap((i) => cities[i] ?? [])
  return info
}
